public sealed class IssueCoordinateContext
{
    public string ModelUrn { get; set; } = ""; public string VersionUrn { get; set; } = ""; public string ViewableGuid { get; set; } = ""; public string ViewableUrn { get; set; } = ""; public string ModelPropertiesGuid { get; set; } = "";
    public string SourceUnits { get; set; } = ""; public UnitParseStatus UnitStatus { get; set; }=UnitParseStatus.Missing; public LengthUnit? Unit { get; set; } public double? MetresPerUnit { get; set; } public LengthUnit? ViewerCoordinateUnit { get; set; } public LengthUnit? ModelDisplayUnit { get; set; } public LengthUnit? PropertyValueUnit { get; set; } public LengthUnit RevitInternalUnit { get; set; }=LengthUnit.Foot; public string Region { get; set; } = "";
    public double[] GlobalOffset { get; set; } = new[]{double.NaN,double.NaN,double.NaN}; public Matrix4 PlacementTransform { get; set; } = Matrix4.Identity(); public Matrix4 LinkToHost { get; set; } = Matrix4.Identity();
    public CoordinateContract Contract { get; set; } public CoordinateSpace PushpinSpace { get; set; } public CoordinateSpace GlobalOffsetSpace { get; set; } public CameraPointContract CameraContract { get; set; }
    public CoordinateTransformDirection PlacementDirection { get; set; } public MatrixSourceFormat MatrixFormat { get; set; }
    public string UnitsSource { get; set; } = ""; public string GlobalOffsetSource { get; set; } = ""; public string PlacementTransformSource { get; set; } = ""; public string ViewableSource { get; set; } = "";
    public CoordinateContractDecision ContractDecision { get; set; }=new(); public string TransformSource { get; set; } = ""; public string ModelDate { get; set; } = ""; public string IncompleteReason { get; set; } = "";
    public List<string> ContextSources { get; set; } = new();
    public bool HasKnownUnits=>UnitStatus==UnitParseStatus.Known&&Unit.HasValue&&MetresPerUnit.HasValue;
    public bool IsComplete => !string.IsNullOrWhiteSpace(ModelUrn) && !string.IsNullOrWhiteSpace(VersionUrn) && !string.IsNullOrWhiteSpace(ViewableGuid) && Contract!=CoordinateContract.Unverified && MatrixMath.IsFinite(GlobalOffset) && MatrixMath.IsInvertible(LinkToHost) && (Contract==CoordinateContract.ViewerLocalFeetPlusGlobalOffset ? ViewerCoordinateUnit==LengthUnit.Foot : HasKnownUnits&&MatrixMath.IsInvertible(PlacementTransform));
}
