public readonly struct CoordinateContextCacheKey : IEquatable<CoordinateContextCacheKey>
{
    public CoordinateContextCacheKey(string projectId,string region,string versionUrn,string viewableGuid){ProjectId=projectId??"";Region=region??"";VersionUrn=versionUrn??"";ViewableGuid=viewableGuid??"";}
    public string ProjectId { get; } public string Region { get; } public string VersionUrn { get; } public string ViewableGuid { get; }
    public bool Equals(CoordinateContextCacheKey other)=>StringComparer.OrdinalIgnoreCase.Equals(ProjectId,other.ProjectId)&&StringComparer.OrdinalIgnoreCase.Equals(Region,other.Region)&&StringComparer.OrdinalIgnoreCase.Equals(VersionUrn,other.VersionUrn)&&StringComparer.OrdinalIgnoreCase.Equals(ViewableGuid,other.ViewableGuid);
    public override bool Equals(object? obj)=>obj is CoordinateContextCacheKey other&&Equals(other);
    public override int GetHashCode(){unchecked{var h=StringComparer.OrdinalIgnoreCase.GetHashCode(ProjectId);h=h*397^StringComparer.OrdinalIgnoreCase.GetHashCode(Region);h=h*397^StringComparer.OrdinalIgnoreCase.GetHashCode(VersionUrn);h=h*397^StringComparer.OrdinalIgnoreCase.GetHashCode(ViewableGuid);return h;}}
    public override string ToString()=>ProjectId+"|"+Region+"|"+VersionUrn+"|"+ViewableGuid;
}
